use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const R:&str="/home/ubuntu/src/zopro-perf-work/fused-dy-hotpath176";
const P:&str="/home/ubuntu/src/zopro-perf-work/fused-incoming-dy176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn txt(p:impl AsRef<Path>)->String{fs::read_to_string(p).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn hex(s:&str)->u64{u64::from_str_radix(s.trim().trim_start_matches("0x"),16).unwrap()}
fn u16at(b:&[u8],i:usize)->u16{u16::from_le_bytes(b[i..i+2].try_into().unwrap())}
fn u32at(b:&[u8],i:usize)->u32{u32::from_le_bytes(b[i..i+4].try_into().unwrap())}
fn u64at(b:&[u8],i:usize)->u64{u64::from_le_bytes(b[i..i+8].try_into().unwrap())}
fn class(op:&str)->&'static str{if op.starts_with("vpmadd52"){"IFMA"}else if op=="vpmullq"{"vector_integer_multiply"}else if op.starts_with("vmov"){"vector_move"}else if op.starts_with('v'){"other_vector"}else if op.starts_with('j'){"branch"}else if op.starts_with('k'){"mask_register"}else if op.starts_with("call"){"call"}else{"other_scalar"}}
fn main(){assert!(!Path::new(&format!("{R}/analysis.json")).exists());assert_eq!(read(format!("{R}/tools/result.json"))["status"],"complete");let pins=read(format!("{R}/tools-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let inp=read(format!("{R}/inputs.json"));let inherited=read(format!("{P}/analysis.json"));let oldsyms=read(format!("{P}/symbols.json"));let mut arms=BTreeMap::new();
 for arm in["OFF","ON"]{let i=&inp[arm];let binary=i["binary"].as_str().unwrap();assert_eq!(hash(binary),i["binary_sha256"]);let caller:Value=serde_json::from_str(txt(i["caller"].as_str().unwrap()).lines().find_map(|s|s.strip_prefix("CALLER ")).unwrap()).unwrap();let pid=caller["pid"].as_u64().unwrap();let tids=caller["worker_rows"].as_array().unwrap().iter().map(|v|v["tid"].as_u64().unwrap()).chain(std::iter::once(pid)).collect::<BTreeSet<_>>();
  let meta=txt(i["metadata"].as_str().unwrap());let matches=meta.lines().filter(|s|s.contains("PERF_RECORD_MMAP2")&&s.contains(binary)&&s.contains("r-xp")&&s.contains(&format!("{pid}/{pid}:"))).collect::<Vec<_>>();assert_eq!(matches.len(),1);let m=matches[0];let t=m.split_once(": [0x").unwrap().1;let(base,after)=t.split_once("(0x").unwrap();let(size,after)=after.split_once(") @ 0x").unwrap();let offset=after.split_whitespace().next().unwrap();let mapbase=hex(base);let mapsize=hex(size);let mapoff=hex(offset);
  let elf=fs::read(binary).unwrap();assert_eq!(&elf[..6],b"\x7fELF\x02\x01");assert_eq!(u16at(&elf,16),3);let phoff=u64at(&elf,32)as usize;let phsize=u16at(&elf,54)as usize;let phn=u16at(&elf,56)as usize;assert_eq!(phsize,56);let segments=(0..phn).map(|n|phoff+n*phsize).filter(|&at|u32at(&elf,at)==1&&u32at(&elf,at+4)&1!=0&&(u64at(&elf,at+8)&!4095)==mapoff).collect::<Vec<_>>();assert_eq!(segments.len(),1);let ph=segments[0];let voff=u64at(&elf,ph+16);let fileoff=u64at(&elf,ph+8);let segmentbytes=u64at(&elf,ph+32);assert!(segmentbytes<=mapsize);let bias=mapbase-(voff&!4095);let naive=mapbase-mapoff;let sym=i["symbol"].as_str().unwrap();let symbols=txt(format!("{R}/tools/symbols-{arm}/stdout.log"));let found=symbols.lines().filter(|s|s.split_whitespace().last()==Some(sym)).collect::<Vec<_>>();assert_eq!(found.len(),1);let f=found[0].split_whitespace().collect::<Vec<_>>();let start=hex(f[0]);let bytes=hex(f[1]);let end=start+bytes;assert!(start>=voff&&end<=voff+segmentbytes);let readelf=txt(format!("{R}/tools/segments-{arm}/stdout.log"));assert!(readelf.lines().any(|s|{let f=s.split_whitespace().collect::<Vec<_>>();f.len()>=8&&f[0]=="LOAD"&&hex(f[1])==fileoff&&hex(f[2])==voff&&f[6]=="R"&&f[7]=="E"}));
  let mut ins=BTreeMap::<u64,(String,String)>::new();for l in txt(format!("{R}/tools/assembly-{arm}/stdout.log")).lines(){let Some((at,text))=l.trim().split_once(':')else{continue;};let Ok(at)=u64::from_str_radix(at,16)else{continue;};let text=text.trim();if at<start||at>=end||text.is_empty(){continue;}let op=text.split_whitespace().next().unwrap();assert!(ins.insert(at,(op.into(),text.into())).is_none());}assert_eq!(*ins.first_key_value().unwrap().0,start);assert!(ins.len()>1000);
  let mut counts=BTreeMap::<u64,u64>::new();let mut total=0u64;let mut func=0u64;let samples=txt(i["samples"].as_str().unwrap());for l in samples.lines(){let f=l.split_whitespace().collect::<Vec<_>>();if f.is_empty()||f[0].starts_with('#'){continue;}assert!(f.len()>=6);let(p,t)=f[0].split_once('/').unwrap();assert_eq!(p.parse::<u64>().unwrap(),pid);assert!(tids.contains(&t.parse().unwrap()));assert!(f[1].trim_matches(['[',']']).parse::<u64>().unwrap()<32);assert_eq!(f[3],"16000000");let ip=hex(f[4]);total+=1;if f[5]!=sym{continue;}assert!(ip>=mapbase&&ip<mapbase+mapsize);let at=ip-bias;assert!(at>=start&&at<end);assert!(ins.contains_key(&at),"sample boundary {at:x}");*counts.entry(at).or_default()+=1;func+=1;}
  assert_eq!(total,inherited["profiles"][format!("cycles-G2-w32-{arm}")]["samples"].as_u64().unwrap());let prior=oldsyms[format!("cycles-G2-w32-{arm}")].as_array().unwrap().iter().filter(|v|v["symbol"].as_str().unwrap().contains("quarter_kernels::G2Scratch>::apply")).collect::<Vec<_>>();assert_eq!(prior.len(),1);assert_eq!(func,prior[0]["samples"].as_u64().unwrap());
  let annotation=txt(format!("{R}/tools/annotate-{arm}/stdout.log"));assert!(annotation.lines().next().unwrap().contains(&format!("({func} samples,")));let mut annotated=BTreeMap::new();for l in annotation.lines(){let Some((n,t))=l.trim().split_once(':')else{continue;};let Ok(n)=n.trim().parse::<u64>()else{continue;};let Some((at,inst))=t.trim().split_once(':')else{continue;};let at=hex(at);assert!(ins.contains_key(&at));assert_eq!(inst.split_whitespace().next().unwrap(),ins[&at].0);assert!(annotated.insert(at,n).is_none());}assert_eq!(annotated.len(),ins.len());for(&at,_)in &ins{assert_eq!(annotated[&at],*counts.get(&at).unwrap_or(&0),"perf annotate count {arm} {at:x}");}assert_eq!(annotated.values().sum::<u64>(),func);
  let mut staticops=BTreeMap::<String,u64>::new();let mut sampledops=BTreeMap::<String,u64>::new();let mut staticclasses=BTreeMap::<String,u64>::new();let mut sampledclasses=BTreeMap::<String,u64>::new();let(mut rspstatic,mut rspsampled,mut rspvector,mut rspifma)=(0u64,0u64,0u64,0u64);let mut rows=Vec::new();let mut prologuereserve=0;for(index,(&at,(op,text)))in ins.iter().enumerate(){let n=*counts.get(&at).unwrap_or(&0);*staticops.entry(op.clone()).or_default()+=1;*sampledops.entry(op.clone()).or_default()+=n;*staticclasses.entry(class(op).into()).or_default()+=1;*sampledclasses.entry(class(op).into()).or_default()+=n;let rsp=text.contains("[rsp");if rsp{rspstatic+=1;rspsampled+=n;if op.starts_with('v'){rspvector+=n;}if op.starts_with("vpmadd52"){rspifma+=n;}}if index<24&&op=="sub"{if let Some(v)=text.split_once("rsp,0x"){prologuereserve+=hex(v.1.split_whitespace().next().unwrap());}}if n>0{rows.push(json!({"address":format!("{at:x}"),"function_offset":at-start,"samples":n,"share_of_function":n as f64/func as f64,"mnemonic":op,"instruction":text,"syntactic_rsp_access":rsp}));}}
  rows.sort_by_key(|v|std::cmp::Reverse(v["samples"].as_u64().unwrap()));arms.insert(arm,json!({"binary":binary,"symbol":sym,"function_start":format!("{start:x}"),"function_bytes":bytes,"static_instructions":ins.len(),"prologue_sub_rsp_bytes":prologuereserve,"executable_mmap":m,"ELF_executable_file_offset":fileoff,"ELF_executable_virtual_address":voff,"runtime_bias":format!("{bias:x}"),"naive_file_offset_bias_error_bytes":naive-bias,"sampled_instructions_exact_boundaries":true,"perf_annotate_every_instruction_count_exact":true,"profile_samples":total,"function_samples":func,"function_profile_share":func as f64/total as f64,"static_mnemonics":staticops,"sampled_mnemonics":sampledops,"static_classes":staticclasses,"sampled_classes":sampledclasses,"syntactic_rsp_static_instructions":rspstatic,"syntactic_rsp_samples":rspsampled,"syntactic_rsp_vector_samples":rspvector,"syntactic_rsp_IFMA_samples":rspifma,"sampled_instruction_rows":rows}));
 }
 let out=json!({"passed":true,"scope":"offline exact mapping of existing two cycle panels; not new recording/timing/proof or causal latency attribution","arms":arms,"all_samples_and_annotation_counts_exact":true,"sampling_skid_not_excluded":true,"new_recordings":0,"new_timings":0,"new_proofs":0,"canonical_proofs":44265,"production_changed":false,"goal_complete":false});fs::write(format!("{R}/analysis.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("MappedOFFandONsamples/ELFPT_LOAD+MMAP2/nmsymbolbounds/everyinstructionboundary;perfannotateallcountsEXACT;no clocks");}
